import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    attacked = []
    for _ in range(m):
        attacked.append(int(next(iterator)))

    attacked_set = set(attacked)

    def bfs(start_node):
        dist = [-1] * (n + 1)
        dist[start_node] = 0
        queue = deque([start_node])
        max_dist = 0

        while queue:
            u = queue.popleft()
            d = dist[u]
            if u in attacked_set:
                if d > max_dist:
                    max_dist = d

            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = d + 1
                    queue.append(v)

        return max_dist, dist

    best_city = None
    min_max_dist = float('inf')

    for start_node in sorted(attacked):
        max_d, _ = bfs(start_node)
        if max_d < min_max_dist:
            min_max_dist = max_d
            best_city = start_node
        elif max_d == min_max_dist:
            if best_city is None or start_node < best_city:
                best_city = start_node

    print(best_city)
    print(min_max_dist)

if __name__ == "__main__":
    solve()
